#include "Editor/VisualScripting/VisualScriptTextEstimate.h"

#include "Strada/Core/Hash.h"

#include <cstddef>

namespace Strada
{
	// Generated by "VisualScriptEditor: the text estimate's advances are the editor font's" (VisualScriptHeadlessCanvasTests.cpp),
	// which prints the table when the font changes.
	std::array<uint16_t, 95> const VisualScriptTextAdvances = {
		// Rows of 16 code points from 32 (space): " !\"#$%&'()*+,-./", "0123456789:;<=>?", "@A-O", "P-_", "`a-o", "p-~".
		14, 15, 18, 34, 32, 41, 35, 10, 20, 20, 25, 31, 12, 18, 16, 22, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 15, 13, 28, 31, 29, 27,
		49, 37, 35, 36, 36, 31, 30, 38, 39, 16, 31, 35, 30, 48, 39, 38, 35, 38, 35, 33, 34, 36, 36, 49, 35, 34, 33, 15, 23, 15, 24, 25,
		18, 30, 31, 29, 31, 30, 20, 31, 31, 14, 14, 29, 14, 48, 31, 32, 31, 32, 20, 29, 19, 31, 28, 41, 28, 27, 28, 19, 14, 19, 37};

	namespace
	{
		bool IsContinuation(unsigned char byte)
		{
			return (byte & 0xC0u) == 0x80u;
		}

		// The bytes of the UTF-8 sequence a lead byte starts; 0 for a byte no sequence starts with.
		size_t GetSequenceLength(unsigned char lead)
		{
			if (lead >= 0xC2u && lead <= 0xDFu)
			{
				return 2;
			}
			if (lead >= 0xE0u && lead <= 0xEFu)
			{
				return 3;
			}
			if (lead >= 0xF0u && lead <= 0xF4u)
			{
				return 4;
			}
			return 0;
		}
	}

	float EstimateVisualScriptTextWidth(std::string_view text, float sizeCu)
	{
		// Sums of the table's 1/64 units and of whole sizes, so the result does not depend on the order of the additions.
		uint64_t advances = 0;
		uint64_t wide = 0;
		size_t index = 0;
		while (index < text.size())
		{
			auto const byte = static_cast<unsigned char>(text[index]);
			if (byte < 0x80u)
			{
				if (byte >= 32u && byte <= 126u)
				{
					advances += VisualScriptTextAdvances[byte - 32u];
				}
				else
				{
					wide++;
				}
				index++;
				continue;
			}
			// One code point counts once; a byte that starts no complete sequence counts on its own (ImGui draws at most one
			// glyph for it).
			size_t const length = GetSequenceLength(byte);
			bool complete = length > 0 && index + length <= text.size();
			for (size_t next = 1; complete && next < length; next++)
			{
				complete = IsContinuation(static_cast<unsigned char>(text[index + next]));
			}
			wide++;
			index += complete ? length : 1;
		}
		float const ascii = static_cast<float>(advances) / 64.0f * VisualScriptTextEstimateMargin;
		return (ascii + static_cast<float>(wide)) * sizeCu;
	}

	VisualScriptTextMeasurer MakeEstimatingVisualScriptTextMeasurer()
	{
		VisualScriptTextMeasurer measure;
		measure.Measure = [](std::string_view text, float sizeCu)
		{
			return EstimateVisualScriptTextWidth(text, sizeCu);
		};
		measure.Signature = Hash::FNV1a("VisualScriptEstimatedText v1");
		return measure;
	}
}
